 "content": "def transform(grid):
    """Complete interrupted horizontal color bars along their vertical rails."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    crossings = {}

    # The missing cells in each horizontal bar are bracketed by colored cells.
    # Fill the gap, and record its row/color as a crossing on that rail.
    for r, row in enumerate(grid):
        nz = [c for c, v in enumerate(row) if v != 0]
        if not nz:
            continue
        left, right = min(nz), max(nz)
        for c in range(left + 1, right):
            if row[c] == 0 and any(row[k] != 0 for k in range(left, c)) and any(row[k] != 0 for k in range(c + 1, right + 1)):
                # At these bar/rail crossings the two sides carry the same bar color.
                color = next(row[k] for k in range(c - 1, left - 1, -1) if row[k] != 0)
                out[r][c] = color
                crossings.setdefault(c, []).append((r, color))

    # A rail's horizontal-bar colors occupy the intervals above/between its
    # crossings; its original lower vertical color continues below the last bar.
    for c, hits in crossings.items():
        hits.sort()
        for i, (r, color) in enumerate(hits):
            start = 0 if i == 0 else hits[i - 1][0] + 1
            for rr in range(start, r + 1):
                out[rr][c] = color
        last_r = hits[-1][0]
        lower_colors = [grid[rr][c] for rr in range(last_r + 1, h) if grid[rr][c] != 0]
        if lower_colors:
            # The lower part is one straight, monochromatic vertical line.
            color = lower_colors[0]
            for rr in range(last_r + 1, h):
                out[rr][c] = color
    return out
